        assert_eq!(bytes, vec![1, 2, 3]);
        assert!(!overflowed);
        assert_eq!(used, 3);

        let (bytes, overflowed) = with_limit(2, || CappedVec::from_slice(&[1, 2, 3]).into_vec());
